from common import *

def make(v):
    p=Paper(2018,v); k=v+1
    p.mc('Divisibility',f'2·3·5·{[11,13,17,19,23][v-1]} үржвэрийн хуваагчийг сонго.',15,'Үржвэрт 3 ба 5 хоёул орсон тул 15-д хуваагдана.',[4,9,25,49])
    p.mc('Proportion',f'{2*k}:x=2:5 бол x хэд вэ?',5*k,'Хөндлөн үржүүлбэл 2x=10k.')
    p.mc('Double inequality',f'{40*k}<47x<{80*k} нөхцөлийг хангах бүхэл тоог сонго.',k+1,'Сонголт бүрийг 47-оор үржүүлж хоёр хязгаартай харьцуул.',[0,k-1,2*k+2,3*k+1])
    a=2*k+1;d=k+2
    p.mc('Arithmetic sequence',f'{a}, {a+d}, {a+2*d}, … дарааллын тавдугаар гишүүнийг ол.',a+4*d,'a₅=a₁+4d.')
    p.mc('Triangle angles','Гурвалжны гурван дотоод өнцөг болох багцыг сонго.',f'(π/{k+2}; π/{k+2}; {k}π/{k+2})','Бүх өнцөг эерэг бөгөөд нийлбэр нь π.', ['(π/3; π/3; π/2)','(π/4; π/4; π/4)','(π/2; π/2; π/3)','(π/6; π/6; π/3)'])
    p.mc('Rectangle ratio',f'Тэгш өнцөгт талбайн урт ба өргөний харьцаа 3:2, талбай {6*(k+2)**2} м². Талуудыг ол.',(3*(k+2),2*(k+2)),'Талууд 3t,2t. 6t²=S.',[(k+2,6*(k+2)),(6*(k+2),k+2),(3*(k+2),3*(k+2)),(2*(k+2),2*(k+2))])
    p.mc('Polyhedron edges',f'Зөв {k+3} өнцөгт суурьтай призм нийт хэдэн ирмэгтэй вэ?',3*(k+3),'Суурь бүр n, холбох n: нийт 3n.')
    N=18+v
    p.mc('Uniform probability',f'1-ээс {N} хүртэл дугаарласан тасалбараас нэгийг сугалбал нэг оронтой дугаартай байх магадлал хэд вэ?',F(9,N),'Нийт N тэнцүү боломж, таатай нь 1,…,9.',[F(8,N),F(10,N),F(1,N),F(2,N)])
    p.mc('Mixed fraction arithmetic',f'({k}/5 ÷ {k}/4 · 1.5 − 0.2) ÷ (1/5) утгыг ол.',5,'Эхний ноогдвор 4/5; 1.5-аар үржүүлж 0.2-ыг хасвал 1; дараа нь 1/5-д хуваана.')
    p.mc('Logarithm power identity',f'{k+3}^(log_{k+3}(tan 45°)) · {k+3}^(log_{k+3}(cot 45°)) утгыг ол.',1,'a^(log_a t)=t; tanθ·cotθ=1.',[0,k+3,(k+3)**2,F(1,k+3)])
    p.mc('Rational expression',f'(a+{k}a/b)/(a−{k}a/b)-г хялбарчил (a≠0, b≠0,{k}).',f'(b+{k})/(b−{k})','Хүртвэр ба хуваарийг b/a-аар үржүүл.',[f'(b−{k})/(b+{k})',f'(b+{k})/b',f'(b−{k})/b',f'a(b+{k})/(b−{k})'])
    p.mc('Radical domain',f'√(x−{k+2})>−{k} тэнцэтгэл бишийн шийдийг ол.',f'[{k+2}; +∞)','Язгуур тодорхой байх x≥k+2 нөхцөл хангалттай.',[f'({k+2}; +∞)',f'(−∞; {k+2}]','R','∅'])
    p.mc('Discrete quadratic minimum',f'aₙ=n²−{2*(k+1)}n+{(k+1)**2+k}, n≥1 дарааллын хамгийн бага утгыг ол.',k,'Квадрат гүйцээвэл (n−(k+1))²+k. Оргилын индекс натурал.')
    p.mc('Special trigonometric values',f'{2*k+3}sin(π/6)−cot(π/4) утгыг ол.',F(2*k+1,2),'sin(π/6)=1/2, cot(π/4)=1.')
    p.mc('Function parity','Тэгш функцийг сонго.',f'sin(2x)/({k}tan x)','sin(2x)/tan x=2cos²x; тодорхойлогдох муж нь тэгш хэмтэй.',[f'cos(2x)/({k}tan x)',f'x cos({k}x)',f'sin({k}x)',f'x³+{k}x'])
    p.mc('Removable limit',f'lim[x→−{k}] (x²+{k-1}x−{k})/(x²−{k*k}) утгыг ол.',F(k+1,2*k),'Хүртвэр=(x+k)(x−1), хуваарь=(x+k)(x−k); хураагаад орлуул.')
    theta=40+2*v
    p.mc('Isosceles angle chase',f'PQ=QR бүхий PQR гурвалжны ∠Q={theta}°. M нь QR дээр, PM=QM. ∠MPR-ийг ол.',F(180-3*theta,2),'Суурийн өнцөг (180−θ)/2; PM=QM тул ∠QPM=θ. Ялгаврыг ав.')
    p.mc('Central angle',f'Тойргийг 1:2:{k+2} харьцаатай гурван нумд хуваав. Хамгийн бага нумын төв өнцөг хэд вэ?',F(360,k+5),'360°-ийг харьцааны нийлбэрт хуваана.')
    a=S.Matrix([k,-2]);b=S.Matrix([1,k+1]);ans=(2*a-3*b).dot(a+b)
    p.mc('Vector dot product',f'a=({k},−2), b=(1,{k+1}) бол (2a−3b)·(a+b)-г ол.',ans,'Эхлээд векторуудын координатыг олж харгалзах координатын үржвэрүүдийг нэм.')
    dest=(3,3);mid=[(1,1),(1,2),(2,1),(2,2),(1,3)][v-1];ways=math.comb(sum(mid),mid[0])*math.comb(6-sum(mid),3-mid[0])
    p.mc('Lattice paths',f'A(0,0)-оос B{mid} цэгийг дайран C(3,3) хүрэхдээ зөвхөн баруун эсвэл дээш нэг нэгж явна. Замын тоог ол.',ways,'A→B ба B→C замын биномиал коэффициентүүдийг үржүүл.',figure={'kind':'lattice','start':[0,0],'via':list(mid),'end':[3,3]})
    p.mc('Transfer word problem',f'Номин түүсэн самрынхаа 1/{k+2}-ийг идэв. Тэмүүлэн өөрийн самрын 1/3-ийг түүнд өгсний дараа тэнцүү самартай болов. Тэмүүлэн анх Номиноос хэд дахин их самартай байсан бэ?',F(3*(k+1),k+2),'Номингийн анхныг N, Тэмүүлэнгийнхийг T гэвэл (k+1)N/(k+2)+T/3=2T/3.')
    c=k+2
    p.mc('Nested radicals',f'(√({c}+√({c*c-1}))−√({c}−√({c*c-1})))² утгыг ол.',2*c-2,'Квадрат задлахад 2c−2√(c²−(c²−1))=2c−2.')
    z=[8,10,14,15,21][v-1];count=2*len(S.divisors(z))
    p.mc('Integer divisors',f'({k}a+{z})/a бүхэл байх тэгээс ялгаатай бүхэл a хэд вэ?',count,'a нь z-ийн эерэг эсвэл сөрөг хуваагч байна.')
    p.mc('Reciprocal percentage',f'Эерэг t тооны {5*(k+2)**2}% нь 1/t тооны 20%-тай тэнцүү. t-г ол.',F(2,k+2),'t²=20/[5(k+2)²]; эерэг язгуурыг ав.')
    base=k+3
    p.mc('Logarithmic equation',f'log_{base}({base+1}−{base}^x)=1−x тэгшитгэлийн шийдүүдийн нийлбэрийг ол.',1,'u=b^x>0 гэвэл u(b+1−u)=b; u=1,b; x=0,1.')
    p.mc('Hyperbola quadrants',f'y=({k}x+{k+1})/x график аль мөчүүдээр дайрах вэ?','I, II, III','y=k+(k+1)/x: x>0 үед I; x<0 үед y эерэг эсвэл сөрөг.', ['I, II, IV','I, III, IV','II, III, IV','I, III'])
    p.mc('Trigonometric identity',f'tan α={k} бол √(2cot α+1/sin²α) утгыг ол.',F(k+1,k),'1/sin²α=1+cot²α тул язгуур дотор (1+cotα)².',points=3)
    p.mc('Velocity',f'Роботын байрлал s(t)={k}t²+{k+1}/t+{k+2}t−7, t>0. t=1 үеийн хурдыг ол.',2*k+1,'s′(t)=2kt−(k+1)/t²+k+2; t=1 орлуул.')
    # Integral polynomial designed to retain two real endpoint solutions.
    p.mc('Integral with parameter',f'∫[b/2→b] (1−2x)/3 dx={F(-k*(3*k-2),12)} байх b утгуудыг ол.',f'{{{k}; {F(2,3)-k}}}','Интеграл b/6−b²/4. Квадрат тэгшитгэлийн язгууруудын нийлбэр 2/3.',[f'{{{k}; {F(2,3)+k}}}',f'{{−{k}; {F(2,3)-k}}}',f'{{{k}; 0}}','∅'],points=3)
    p.mc('Cylinder axial section',f'Цилиндрийн тэнхлэг огтлол нь {k+3}√2 диагональтай квадрат. Хажуу гадаргуугийн талбайг ол.',f'{(k+3)**2}π','Квадратын тал h=2r=k+3; 2πrh=πh².',[f'{2*(k+3)**2}π',f'{(k+3)**2}/2·π',f'{k+3}π',f'{2*(k+3)}π'])
    r=[10,15,25,30,40][v-1]
    p.mc('Surface area scaling',f'Савангийн урт, өргөн, өндөр тус бүр {r}%-иар багасав. Гадаргуугийн талбай хэдэн хувиар багасах вэ?',F(10000-(100-r)**2,100),'Ижил төст биетийн талбайн харьцаа (1−r/100)².')
    data=[k+1,k+4,k+7,k+6,k+1,k+8,k+4,k+5,k+1,k+8]
    p.mc('Mode and median',f'Нэгж хугацаанд хэмжсэн утгууд: {data}. (Моод; медиан)-ыг ол.',(k+1,F(2*k+9,2)),'Эрэмбэлэхэд 5 ба 6 дахь нь k+4,k+5; k+1 хамгийн олон давтана.',[(k+8,F(2*k+9,2)),(k+1,k+4),(k+1,k+5),(k+4,k+1)],points=2)
    p.mc('Ordering irrational exponents',f'{base}^(∛5), {base}^(∜7), {base}^(√3) тоонуудыг буурахаар эрэмбэл.','√3, ∛5, ∜7','Суурь>1; илтгэгчдийг 12 зэрэгт дэвшүүлбэл 729>625>343.', ['∛5, √3, ∜7','∜7, √3, ∛5','√3, ∜7, ∛5','∜7, ∛5, √3'])
    p.mc('Change of logarithm base',f'log_{base}2=a бол log_{2*base}({4*base})-г a-гаар илэрхийл.','(2a+1)/(a+1)','Хүртвэрийг log_b(4b)=2a+1, хуваарийг log_b(2b)=a+1 болгон бич.', ['(a+1)/(2a+1)','(2a−1)/(a+1)','2a/(a+1)','(2a+1)/(a−1)'])
    mass=80+10*k
    p.mc('Drying mixture',f'{mass} кг жимсний 96% нь ус. Хатаасны дараа усны эзлэх хувь 92% болов. Шинэ массыг ол.',F(mass,2),'Хуурай бодисын масс хадгалагдана: 0.04M=0.08m.')
    a=k;b=k+1;c=k+3
    p.mc('Antiderivative initial condition',f'f′(x)=1/((x−{a})(x−{b})), x>{b}; f({c})=ln(2/3). f(x)-г ол.',f'ln| (x−{b})/(x−{a}) |','Хэсэг бутархай болгон интегралдвал ln|(x−b)/(x−a)|+C; өгсөн цэгт C=0.',[f'ln|(x−{a})/(x−{b})|',f'ln|(x−{b})/(x−{a})|+ln2',f'ln|(x−{b})/(x−{a})|−ln2',f'1/(x−{a})−1/(x−{b})'])
    n=k+4
    p.multi('2.1','Triangle inequality and trig',f'1, |sin(α/{n})|, cos(π/3) уртууд үл дорой гурвалжин үүсгэх бүх α-г ол. k нь бүхэл тоо.', [('Гурав дахь талын утга',F(1,2)),('Шаардлагатай |sin(α/n)| доод хязгаар',F(1,2)),('α завсрын зүүн зах (модулиар nπ)',simplest(S.Rational(n,6)*S.pi)),('α завсрын баруун зах (модулиар nπ)',simplest(S.Rational(5*n,6)*S.pi))],f'Гурвалжны тэнцэтгэл биш |sin(α/{n})|>1/2. Иймд {simplest(S.Rational(n,6)*S.pi)}+{n}πk<α<{simplest(S.Rational(5*n,6)*S.pi)}+{n}πk.')
    h=k;q=1-k;line=2;inter=q-2*h
    p.multi('2.2','Parabola line and area',f'Тэргүүлэх коэффициент 1, орой ({h},{q}) парабол ба (0,{inter}), (2,{inter+2*line}) цэгийг дайрсан шулууныг авч үз.', [('Параболын x коэффициент',-2*h),('Параболын тогтмол гишүүн',h*h+q),('Шулууны налалт',line),('Хоёр графикийн хоорондох талбай',S.Rational(4,3))],'u=x−h гэвэл шулуун−парабол=2u−u². 0-ээс 2 хүртэл интеграл 4/3.')
    probs=[F(k+1,10),F(5,10),F(8,10)];total=sum(probs)/3
    p.multi('2.3','Total and conditional probability',f'Гурван хайрцагт биологи, газарзүй, физикийн асуулт тус тус бий. Хайрцаг бүр ижил магадлалаар сонгогдоно. Сурагчийн мэдэх асуултын эзлэх хувь харгалзан {10*(k+1)}%, 50%, 80%. Сонгосон хайрцаг дотроос нэг асуултыг жигд сугална.', [('Физикийн хайрцаг сонгох магадлал',F(1,3)),('Физикийн асуултыг мэдэх нөхцөлт магадлал',F(4,5)),('Мэдэх асуулт таарах магадлал',total),('Мэдэх асуулт физикийнх байх магадлал',F(4,15)/total)],'Нийт магадлал нь гурван нөхцөлт магадлалын дундаж. Байесын томьёонд (1/3)(4/5)-ыг нийт магадлалд хуваана.')
    R=F(k+3,2);H=k
    p.multi('2.4','Cone inscribed triangular prism optimization',f'Өндөр {H}, суурийн диаметр {2*R} конуст зөв гурвалжин суурьтай призм багтаав. Доод суурь конусын суурь дээр, дээд гурвалжны оройнууд хажуу гадаргуу дээр байна. Гурвалжны тал x.', [('Конусын эзлэхүүний π-ийн коэффициент',R*R*H/3),('Призмийн өндөр h(x)',simplest(H*(1-x/(S.nsimplify(R)*S.sqrt(3))))),('Эзлэхүүн ихсэх үеийн x',simplest(2*S.nsimplify(R)/S.sqrt(3))),('Призмийн хамгийн их эзлэхүүний √3-ийн коэффициент',F(H)*R*R/9)],'Төсөөгөөр h=H(1−x/(R√3)). V=√3·x²h/4; V′=0 үед x=2R√3/3; Vmax=√3·HR²/9.',figure={'kind':'cone_with_regular_triangular_prism','radius':str(R),'height':H})
    p.save()

if __name__=='__main__':
    for v in range(1,6): make(v)
